const pw=require('/tmp/paper-render/node_modules/playwright');
(async()=>{const browser=await pw.chromium.launch({executablePath:'/usr/bin/google-chrome',args:['--no-sandbox'],headless:true});try{const page=await browser.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('file://'+process.cwd()+'/paper/fabius-system.html');await page.evaluate(()=>MathJax.startup.promise);await page.evaluate(()=>document.fonts.ready);const math=await page.locator('mjx-container').count();if(math<50||errors.length)throw Error(JSON.stringify({math,errors}));await page.pdf({path:'paper/fabius-as-a-system.pdf',preferCSSPageSize:true,printBackground:true});console.log(JSON.stringify({math,errors}));}finally{await browser.close();}})().catch(e=>{console.error(e);process.exit(1)});
